#define R iResolution

// fire gradient - array of .r, .g, .b are colors and .a stores the position .0 .. .1 in the gradient. 
const vec4[] fg = vec4 [] ( 
    //    r    g    b    a (=pos in gradient)
    vec4( .0, .0, .0, .0),
    vec4( .1, .1, .1, .1),
    vec4( .3, .0, .0, .2),
    vec4( 1., .4, .0, .5),
    vec4( 1., 1., .3, .7),
    vec4( 1., 1., 1., .8),
    vec4( 1., 1., 1., 1.)
);    

// gradient() calculates a color at pos "pos" 0. .. 1. using definitions in the array fg (fire gradient).
// First I wanted to pass the gradient as a parameter but then I thought it would be faster to
// use the const directly instead to improve performance. So it is not neccessary to copy the whole array
// into a function call for every single pixel. It's my imagination, maybe I am wrong and arrays
// will be passed by reference like Javascript. We'll see.
vec3 gradient( in float pos ) {
    int num_cols = fg.length();
    pos = clamp( pos, 0., 1.); // it needs to be in 0..1 range
    for( int i = 0; i < num_cols-1; i++ ) 
      if( (pos >= fg[i].a) && (pos < fg[i+1].a) ) 
          return mix( 
              fg[i].rgb, 
              fg[i+1].rgb,
              (pos - fg[i].a) / (fg[i+1].a - fg[i].a)
          );
    return fg[ num_cols-1 ].rgb;
}

void mainImage( out vec4 C, in vec2 S ) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = S/R.xy;

    // get the brightness from the black and white image in iChannel0
    float brightness = texture(iChannel0, uv).r;

    // lookup into the gradient and color the pixel 
    C = vec4 ( gradient(2.*brightness), 1.);
}

