// draws an epicycloid graph defined as an array of vec3(freq, amplitude, phase)
// the whole figure will be drawn in interval [ 0. <= t < 2*pi ] + k*2*pi 
vec2 epicycloid(in float t, in vec2 spec[43]) {
    vec2 o = v2;
    float freq = -21.*t;     // calc start freq outside of the loop
    for(int n=0;n<43;n++) {        
         o += spec[n].x             // amplitude 
             * cos(
                 freq              // freq * t
                 + spec[n].y       // + phase = angle;
                 + vec2(0.,-1.57)  // + vec2(0., -1/2*pi) gives cos(angle)+i*sin(angle)
               ); 
        freq += t;
    }
    return zoom * o;
}

// 8< based on https://www.shadertoy.com/view/MlcGDB
// draw line segment from A to B with given thickness r, 
float segment(in vec2 P, in vec2 A, in vec2 B, in float r) {
    vec2 g = B - A;
    vec2 h = P - A;
    float d = length(h - g * clamp(dot(g, h) / dot(g,g), 0.0, 1.0));
    // return smoothstep(r, 0.5*r, d);     // original has bright points where segments overlap
	return smoothstep(r, 0., d-r); //-smoothstep(r,0.,length(h));  
}
// 8< end snip

void mainImage( out vec4 C, in vec2 S )  {     // C=Color of the pixel, S=Screen coordinate of the pixel
    // canvas coordinates
    float line_width = 1.5/R.y;
    float t = iTime;
    vec2 uv = S.xy/vec2(R.y);
    vec2 center = .5*R.xy/R.y;

    // CALC

      //           drawing     path                  xpos   move up and down   yofs             
    vec2 graph_1 = epicycloid(t*1.5,      spectrum_two ) + vec2( -.6, .25 * sin(t*0.01)   -.05);
    vec2 graph_2 = epicycloid(t*2.,       spectrum_zero) + vec2( -.2,-.25 * sin(t*0.009)  -.05);
    vec2 graph_3 = epicycloid(-t*1.1,     spectrum_two ) + vec2(  .2, .25 * sin(t*0.0011) -.05);
    vec2 graph_4 = epicycloid(sin(t)*3.2, spectrum_five) + vec2(  .6,-.25 * sin(t*0.006)  -.05);

    vec4 oldpos_texel_1 = vec4( graph_1, v2);
    vec4 oldpos_texel_2 = vec4( graph_2, v2);
    vec4 oldpos_texel_3 = vec4( graph_3, v2);
    vec4 oldpos_texel_4 = vec4( graph_4, v2);

    // READ
    float o = texelFetch(iChannel0, ivec2(S), 0).r;

    // DRAW
    if(iFrame > 0) {
        oldpos_texel_1 = texelFetch( iChannel0, OLD_POS_1, 0 );
        oldpos_texel_2 = texelFetch( iChannel0, OLD_POS_2, 0 );
        oldpos_texel_3 = texelFetch( iChannel0, OLD_POS_3, 0 );
        oldpos_texel_4 = texelFetch( iChannel0, OLD_POS_4, 0 );
        o = max( o, segment(uv, center+oldpos_texel_1.xy, center+graph_1, line_width) );  // LINES 
        o = max( o, segment(uv, center+oldpos_texel_2.xy, center+graph_2, line_width) );  // LINES 
        o = max( o, segment(uv, center+oldpos_texel_3.xy, center+graph_3, line_width) );  // LINES 
        o = max( o, segment(uv, center+oldpos_texel_4.xy, center+graph_4, line_width) );  // LINES 
    } else {
        o = max( o, smoothstep(line_width, 0., distance(uv, center+graph_1) ) );  // DOTS
        o = max( o, smoothstep(line_width, 0., distance(uv, center+graph_2) ) );  // DOTS
        o = max( o, smoothstep(line_width, 0., distance(uv, center+graph_3) ) );  // DOTS
        o = max( o, smoothstep(line_width, 0., distance(uv, center+graph_4) ) );  // DOTS
    }
    oldpos_texel_1.xy = graph_1;
    oldpos_texel_2.xy = graph_2;
    oldpos_texel_3.xy = graph_3;
    oldpos_texel_4.xy = graph_4;

    // smooth the whole buffer
    C = (S.y>2.) 
        ? ( vec4( vec3(o), 1.)                               // sum up 5 pixels
          +texelFetch(iChannel0, ivec2(S.x - 1., S.y), 0) 
          +texelFetch(iChannel0, ivec2(S.x + 1., S.y), 0) 
          +texelFetch(iChannel0, ivec2(S.x, S.y+1.), 0) 
          +texelFetch(iChannel0, ivec2(S.x, S.y-1.), 0) )
          * 0.1993                                            // divide by a bit more than 5 to slightly dim per frame
        : C;

    // WRITE
    C = ( ivec2(S) == OLD_POS_1 ) ? oldpos_texel_1 : C; 
    C = ( ivec2(S) == OLD_POS_2 ) ? oldpos_texel_2 : C; 
    C = ( ivec2(S) == OLD_POS_3 ) ? oldpos_texel_3 : C; 
    C = ( ivec2(S) == OLD_POS_4 ) ? oldpos_texel_4 : C; 
}
